from __future__ import annotations

import time

from ..filecollector.filecollector import FileCollector
from ..ssh import SshConnectionAdapter
from ..utils.decorator import StateAllowed
from ..wts.edaemon import Edaemon
from ..wts.egate import Egate


class WTSStateMachine:

    def __init__(self, alias: str | None = None):
        self._egates = []
        self._edaemons = []
        self.alias = alias
        StateAllowed.set_state("INIT", alias)

    @property
    def egates(self) -> list:
        """Returns list of available egates objects."""
        return [each[0] for each in self._egates]

    @property
    def edaemons(self) -> list:
        """Returns list of available edaemon objects."""
        return self._edaemons

    @StateAllowed("INIT")
    def add_egate(
        self,
        egate: Egate,
        cfg_file: str | None = None,
        suite_file: str | None = None,
        timeout: float | None = None,
        retry: int = 0,
    ) -> None:
        """Adds egate instance to the state machine.

        :param egate: Egate object.
        :param string cfg_file:   Path to lua configuration file required to configure egate application.
        :param string suite_file: Path to xml configuration file required to configure suite for egate application.
        :param float  timeout:    Timeout for configure operation.
        :param int retry:        Number of times the user want to retry the process.
        """
        self._egates.append([egate, cfg_file, suite_file, timeout, retry])

    @StateAllowed("INIT")
    def add_edaemons(self, edaemons: list[Edaemon]) -> None:
        """Adds edaemon instance to the state machine.

        :param edaemon: Edaemon instance.
        """
        for each in edaemons:
            self._edaemons.append(each)

    @StateAllowed("INIT")
    def start(self) -> None:
        """Starts edaemon and egate applications. Configures egate process if cfg_file or suite_file were provided."""
        for each in self.edaemons:
            each.setup()
        for each in self._egates:
            each[0].setup()
            each[0].configure_egate(*each[1:])
        StateAllowed.set_state("STARTED", self.alias)

    @StateAllowed("ANY")
    def reconnect(self) -> None:
        """Reconnects to a currently running egate process. Configures egate process if cfg_file or suite_file were provided."""
        for each in self.edaemons:
            each.setup(reconnect=True)
        for each in self._egates:
            each[0].setup(reconnect=True)
            time.sleep(1)
            each[0].configure_egate(*each[1:])
        StateAllowed.set_state("STARTED", self.alias)

    @StateAllowed("STARTED")
    def stop(self, **kwargs) -> None:
        """Stops edaemon and egate applications."""
        self._shutdown_applications()
        StateAllowed.set_state("INIT", self.alias)

    @StateAllowed("ANY")
    def get_egates_logs(self, files_list: list, unzip: bool, subdir: str) -> None:
        """Downloads egate logs to machine where Robot Framework test was executed.

        :param list    files_list: List of files to download. Each entry can be specify directly or by simple shell regexp.
        :param boolean unzip:      True file will configure library to unzip log on destination machine.
        :param string  subdir:     Name of sub-directory where file should be stored.
        """
        for each in self.egates:
            name = f"wtssim_egate_{each.port}.tar.gz"
            self._get_log(name, each.client, each.tool_dir, files_list, unzip, subdir)

    @StateAllowed("ANY")
    def get_edaemons_logs(self, files_list: list, unzip: bool, subdir: str) -> None:
        """Downloads edaemon logs to machine where Robot Framework test was executed.

        :param list    files_list: List of files to download. Each entry can be specify directly or by simple shell regexp.
        :param boolean unzip:      True file will configure library to unzip log on destination machine.
        :param string  subdir:     Name of sub-directory where file should be stored.
        """
        for each in self.edaemons:
            name = f"wtssim_edaemon_{each.port}.tar.gz"
            self._get_log(name, each.client, each.tool_dir, files_list, unzip, subdir)

    @StateAllowed("INIT")
    def close_all_connections(self) -> None:
        """Closes every SSH connection available during start procedure."""
        self._close_all_connections()

    @StateAllowed("INIT")
    def set_egate_params(
        self,
        cfg_file: str | None = None,
        suite_file: str | None = None,
        timeout: float | None = None,
        retry: int = 0,
    ) -> None:
        """Sets egate configuration parameters for all instances.

        :param string cfg_file:   Path to lua configuration file required to configure egate application.
        :param string suite_file: Path to xml configuration file required to configure suite for egate application.
        :param float timeout:    Timeout for configure operation.
        :param int retry:        Number of times the user want to retry the process.
        """
        for each in self._egates:
            each[1] = cfg_file if cfg_file else each[1]
            each[2] = suite_file if timeout else each[2]
            each[3] = timeout if timeout else each[3]
            each[4] = retry

    def _get_log(
        self,
        name: str,
        client: SshConnectionAdapter,
        tool_dir: str,
        files_list: list,
        unzip: bool,
        subdir: str,
    ) -> None:
        files_list = [entry.format(tool_dir) for entry in files_list]
        FileCollector(ssh_client=client, tar_name=name).get_files(
            files_list=files_list, unzip=unzip, subdirectory=subdir
        )

    def _close_all_connections(self) -> None:
        for each in self.egates:
            each.client.close()
        for each in self.edaemons:
            each.client.close()

    def _shutdown_applications(self) -> None:
        for each in self.egates:
            each.teardown()
        for each in self.edaemons:
            each.teardown()
